#!/usr/bin/env node
// Applies config/binfire.config.json to every port and to shared/web.
//
//   node tools/configure.mjs           write all generated outputs
//   node tools/configure.mjs --check   exit 1 if any output is stale (CI)
//
// Two kinds of output:
//  1. Whole generated files (runtime config, registry and bridge copies, .well-known files).
//  2. Marked blocks inside hand-maintained files, between lines containing
//     ">>> binfire:configure <name>" and "<<< binfire:configure <name>". Only the
//     lines between the markers are replaced; edit everything else freely.
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const cfg = JSON.parse(readFileSync(join(root, 'config/binfire.config.json'), 'utf8'));
const registryText = readFileSync(join(root, cfg.registry), 'utf8');
const bridgeText = readFileSync(join(root, 'shared/bridge/binfire-bridge.js'), 'utf8');
const D = cfg.linkDomain, S = cfg.scheme;
// '/a/' is a prefix; the others are exact paths, also accepted with a trailing slash (spec/links.md).
const LINK_PATHS = ['/a/', '/open', '/open/', '/c', '/c/', '/s', '/s/'];
const runtimeConfig = JSON.stringify({
  appName: cfg.appName, linkDomain: D, scheme: S, hashbin: cfg.hashbin, ble: cfg.ble, limits: cfg.limits,
  oauthRedirect: `${S}://oauth`,
}, null, 2) + '\n';

let stale = [];
function emit(path, content) {
  const full = join(root, path);
  const old = existsSync(full) ? readFileSync(full, 'utf8') : null;
  if (old === content) return;
  if (check) { stale.push(path); return; }
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, content);
  console.log('wrote', path);
}
function block(path, name, lines) {
  const full = join(root, path);
  const text = readFileSync(full, 'utf8');
  const all = text.split('\n');
  const start = all.findIndex(l => l.includes(`>>> binfire:configure ${name}`));
  const end = all.findIndex((l, i) => i > start && l.includes(`<<< binfire:configure ${name}`));
  if (start < 0 || end < 0) throw new Error(`${path}: missing binfire:configure ${name} markers`);
  const indent = all[start].match(/^\s*/)[0];
  const body = lines.map(l => (l ? indent + l : l));
  emit(path, [...all.slice(0, start + 1), ...body, ...all.slice(end)].join('\n'));
}
const xmlEscape = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// ------------------------------------------------------------- shared/web
const appleIds = [cfg.ids.ios, cfg.ids.flutter, cfg.ids.reactNative].map(id => `${cfg.apple.teamId}.${id}`);
emit('shared/web/.well-known/apple-app-site-association', JSON.stringify({
  applinks: { details: [{ appIDs: appleIds, components: [
    { '/': '/a/*', comment: 'app state' }, { '/': '/open', comment: 'any registered app URL' },
    { '/': '/open/', comment: 'any registered app URL' },
    { '/': '/c', comment: 'HashBin document' }, { '/': '/c/', comment: 'HashBin document' },
    { '/': '/s', comment: 'packaged site' }, { '/': '/s/', comment: 'packaged site' },
    { '/': '/oauth', comment: 'HashBin OAuth redirect' },
  ] }] },
  webcredentials: { apps: appleIds },
}, null, 2) + '\n');
emit('shared/web/.well-known/assetlinks.json', JSON.stringify(
  [cfg.ids.android, cfg.ids.flutter, cfg.ids.reactNative].map(pkg => ({
    relation: ['delegate_permission/common.handle_all_urls'],
    target: { namespace: 'android_app', package_name: pkg, sha256_cert_fingerprints: cfg.android.sha256CertFingerprints },
  })), null, 2) + '\n');
emit('shared/web/404.html', readFileSync(join(root, 'shared/web/index.html'), 'utf8'));
emit('shared/web/registry.js', `// Generated by tools/configure.mjs. Do not edit.\nwindow.BINFIRE_CONFIG = ${JSON.stringify({ linkDomain: D, scheme: S, content: cfg.hashbin.content })};\nwindow.BINFIRE_REGISTRY = ${registryText.trim()};\n`);

// ------------------------------------------------------------- runtime copies
const copies = {
  ios: 'ios/App/Resources',
  android: 'android/app/src/main/assets/binfire',
  flutter: 'flutter/assets/binfire',
};
for (const dir of Object.values(copies)) {
  emit(`${dir}/binfire.config.json`, runtimeConfig);
  emit(`${dir}/apps.json`, registryText);
  emit(`${dir}/binfire-bridge.js`, bridgeText);
}
emit('react-native/src/generated/shared.ts',
  '// Generated by tools/configure.mjs. Do not edit.\n' +
  `export const config = ${runtimeConfig.trim()} as const;\n\n` +
  `export const registry = ${registryText.trim()};\n\n` +
  `export const bridgeSource = ${JSON.stringify(bridgeText)};\n`);

// ------------------------------------------------------------- Android (native)
function androidIntentFilters() {
  const https = LINK_PATHS.map(p => p === '/a/'
    ? `<data android:pathPrefix="${p}" />` : `<data android:path="${p}" />`);
  return [
    '<intent-filter android:autoVerify="true">',
    '    <action android:name="android.intent.action.VIEW" />',
    '    <category android:name="android.intent.category.DEFAULT" />',
    '    <category android:name="android.intent.category.BROWSABLE" />',
    '    <data android:scheme="https" />',
    `    <data android:host="${D}" />`,
    ...https.map(l => '    ' + l),
    '</intent-filter>',
    '<intent-filter>',
    '    <action android:name="android.intent.action.VIEW" />',
    '    <category android:name="android.intent.category.DEFAULT" />',
    '    <category android:name="android.intent.category.BROWSABLE" />',
    `    <data android:scheme="${S}" />`,
    '</intent-filter>',
    '<intent-filter>',
    '    <action android:name="android.intent.action.SEND" />',
    '    <category android:name="android.intent.category.DEFAULT" />',
    '    <data android:mimeType="text/plain" />',
    '</intent-filter>',
    '<intent-filter>',
    '    <action android:name="android.intent.action.VIEW" />',
    '    <category android:name="android.intent.category.DEFAULT" />',
    '    <category android:name="android.intent.category.BROWSABLE" />',
    '    <data android:scheme="content" />',
    '    <data android:scheme="file" />',
    '    <data android:mimeType="application/vnd.binfire.bundle" />',
    '</intent-filter>',
    '<intent-filter>',
    '    <action android:name="android.intent.action.VIEW" />',
    '    <category android:name="android.intent.category.DEFAULT" />',
    '    <data android:scheme="content" />',
    '    <data android:scheme="file" />',
    '    <data android:host="*" />',
    '    <data android:mimeType="*/*" />',
    '    <data android:pathPattern=".*\\\\.binfire" />',
    '</intent-filter>',
  ];
}
block('android/app/src/main/AndroidManifest.xml', 'intent-filters', androidIntentFilters());
block('android/app/build.gradle.kts', 'application-id', [`applicationId = "${cfg.ids.android}"`]);

// ------------------------------------------------------------- Flutter
block('flutter/android/app/src/main/AndroidManifest.xml', 'intent-filters', androidIntentFilters());
block('flutter/android/app/build.gradle.kts', 'application-id', [`applicationId = "${cfg.ids.flutter}"`]);
function plistUrlTypes() {
  return [
    '<key>CFBundleURLTypes</key>',
    '<array>',
    '\t<dict>',
    '\t\t<key>CFBundleURLName</key>',
    `\t\t<string>${xmlEscape(S)}</string>`,
    '\t\t<key>CFBundleURLSchemes</key>',
    `\t\t<array><string>${xmlEscape(S)}</string></array>`,
    '\t</dict>',
    '</array>',
    '<key>CFBundleDocumentTypes</key>',
    '<array>',
    '\t<dict>',
    '\t\t<key>CFBundleTypeName</key><string>binfire bundle</string>',
    '\t\t<key>LSHandlerRank</key><string>Owner</string>',
    '\t\t<key>LSItemContentTypes</key><array><string>app.binfire.bundle</string></array>',
    '\t</dict>',
    '</array>',
    '<key>UTExportedTypeDeclarations</key>',
    '<array>',
    '\t<dict>',
    '\t\t<key>UTTypeIdentifier</key><string>app.binfire.bundle</string>',
    '\t\t<key>UTTypeDescription</key><string>binfire bundle</string>',
    '\t\t<key>UTTypeConformsTo</key><array><string>public.data</string></array>',
    '\t\t<key>UTTypeTagSpecification</key>',
    '\t\t<dict>',
    '\t\t\t<key>public.filename-extension</key><array><string>binfire</string></array>',
    '\t\t\t<key>public.mime-type</key><array><string>application/vnd.binfire.bundle</string></array>',
    '\t\t</dict>',
    '\t</dict>',
    '</array>',
    '<key>LSSupportsOpeningDocumentsInPlace</key><false/>',
  ];
}
block('flutter/ios/Runner/Info.plist', 'url-types', plistUrlTypes());
emit('flutter/ios/Runner/Runner.entitlements', entitlementsPlist());
function entitlementsPlist() {
  return `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<!-- Generated by tools/configure.mjs. Do not edit. -->
<plist version="1.0">
<dict>
\t<key>com.apple.developer.associated-domains</key>
\t<array>
\t\t<string>applinks:${D}</string>
\t\t<string>webcredentials:${D}</string>
\t</array>
</dict>
</plist>
`;
}
block('flutter/ios/ShareExtension/ShareExtension.xcconfig', 'share-extension-id', [
  `PRODUCT_BUNDLE_IDENTIFIER = ${cfg.ids.flutter}.share`,
]);
{
  // Flutter's Xcode project is generated by `flutter create`, so only the bundle id is patched.
  const pbx = 'flutter/ios/Runner.xcodeproj/project.pbxproj';
  const text = readFileSync(join(root, pbx), 'utf8')
    .replace(/PRODUCT_BUNDLE_IDENTIFIER = [^;]*?(\.RunnerTests)?;/g, (_, tests) => `PRODUCT_BUNDLE_IDENTIFIER = ${cfg.ids.flutter}${tests ?? ''};`);
  emit(pbx, text);
}

// ------------------------------------------------------------- iOS (native)
block('ios/project.yml', 'target-settings', [
  `PRODUCT_BUNDLE_IDENTIFIER: ${cfg.ids.ios}`,
]);
block('ios/project.yml', 'share-extension-settings', [
  `PRODUCT_BUNDLE_IDENTIFIER: ${cfg.ids.ios}.share`,
]);
block('ios/project.yml', 'info-properties', [
  'CFBundleURLTypes:',
  `  - CFBundleURLName: ${S}`,
  `    CFBundleURLSchemes: [${S}]`,
  'CFBundleDocumentTypes:',
  '  - CFBundleTypeName: binfire bundle',
  '    LSHandlerRank: Owner',
  '    LSItemContentTypes: [app.binfire.bundle]',
  'UTExportedTypeDeclarations:',
  '  - UTTypeIdentifier: app.binfire.bundle',
  '    UTTypeDescription: binfire bundle',
  '    UTTypeConformsTo: [public.data]',
  '    UTTypeTagSpecification:',
  '      public.filename-extension: [binfire]',
  '      public.mime-type: [application/vnd.binfire.bundle]',
  'LSSupportsOpeningDocumentsInPlace: false',
]);
block('ios/project.yml', 'entitlements', [
  'com.apple.developer.associated-domains:',
  `  - applinks:${D}`,
  `  - webcredentials:${D}`,
]);

// ------------------------------------------------------------- React Native (Expo config)
{
  const path = 'react-native/app.json';
  const app = JSON.parse(readFileSync(join(root, path), 'utf8'));
  const e = app.expo;
  e.scheme = S;
  e.ios = { ...e.ios, bundleIdentifier: cfg.ids.reactNative, associatedDomains: [`applinks:${D}`, `webcredentials:${D}`],
    infoPlist: { ...(e.ios?.infoPlist ?? {}),
      CFBundleDocumentTypes: [{ CFBundleTypeName: 'binfire bundle', LSHandlerRank: 'Owner', LSItemContentTypes: ['app.binfire.bundle'] }],
      UTExportedTypeDeclarations: [{ UTTypeIdentifier: 'app.binfire.bundle', UTTypeDescription: 'binfire bundle', UTTypeConformsTo: ['public.data'],
        UTTypeTagSpecification: { 'public.filename-extension': ['binfire'], 'public.mime-type': ['application/vnd.binfire.bundle'] } }],
      LSSupportsOpeningDocumentsInPlace: false } };
  e.android = { ...e.android, package: cfg.ids.reactNative, intentFilters: [
    { action: 'VIEW', autoVerify: true, category: ['BROWSABLE', 'DEFAULT'],
      data: LINK_PATHS.map(p => p === '/a/' ? { scheme: 'https', host: D, pathPrefix: p } : { scheme: 'https', host: D, path: p }) },
    { action: 'VIEW', category: ['BROWSABLE', 'DEFAULT'], data: [{ scheme: 'content', mimeType: 'application/vnd.binfire.bundle' }] },
  ] };
  emit(path, JSON.stringify(app, null, 2) + '\n');
}

if (check) {
  if (stale.length) { console.error('Stale generated outputs (run node tools/configure.mjs):\n  ' + stale.join('\n  ')); process.exit(1); }
  console.log('configure: all outputs up to date');
}
